uniform float amzp_moreDamage;
uniform float amzp_moreOften;
uniform float amzp_punchIt;
uniform float amzp_effectScale;
uniform float amzp_randomSeed;
uniform float amzp_colorizeOn;
uniform float amzp_srcBrightness;
uniform float amzp_srcContrast;
uniform float amzp_highlightR;
uniform float amzp_highlightG;
uniform float amzp_highlightB;
