uniform float amzp_colorizeAmt;
uniform float amzp_glowOn;
uniform float amzp_glowThresh;
uniform float amzp_glowRadius;
uniform float amzp_glowIntensity;
uniform float amzp_scanLinesOn;
uniform float amzp_scanDistance;
uniform float amzp_scanThickness;
uniform float amzp_scanDir;
uniform float amzp_linesOn;
uniform float amzp_lineSpeed;
