uniform float amzp_glitchSize;
uniform float amzp_glitchSpeed;
uniform float amzp_flickerOn;
uniform float amzp_flickerMin;
uniform float amzp_flickerChance;
uniform float amzp_lowResOn;
uniform float amzp_lowResPct;
uniform float amzp_tvDistOn;
uniform float amzp_tvDistAmt;
uniform float amzp_blend;


        float hashV(float2 p) {
            return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
        }

        float noiseV(float2 p) {
            float2 i = floor(p);
            float2 f = fract(p);
            f = f*f*(3.0-2.0*f);
            return mix(
                mix(hashV(i),           hashV(i+float2(1,0)), f.x),
                mix(hashV(i+float2(0,1)), hashV(i+float2(1,1)), f.x),
                f.y
            );
        }

        void amzRender() {
            float2 uv  = amzScreenNorm();
            float t  = time;
            float sc = amzp_effectScale;
            float4 src = amzTexture(0, clamp(uv, 0.0, 1.0));




            float2 sampleUV = uv;
            if ((amzp_lowResOn>0.5)) {
                float res = max(amzp_lowResPct, 0.05);
                float2 blockSize = float2(1.0) / (screen.zw * res);
                sampleUV = floor(uv / blockSize) * blockSize + blockSize * 0.5;
                sampleUV = clamp(sampleUV, 0.0, 1.0);
