            if ((amzp_tvDistOn>0.5)) {
                float tvWave = noiseV(float2(uv.y * 5.0, t * 2.0)) * 2.0 - 1.0;
                sampleUV.x += tvWave * amzp_tvDistAmt * amzp_moreDamage;
                sampleUV = clamp(sampleUV, 0.0, 1.0);
            }

            float3 col = amzTexture(0, sampleUV).rgb;





            if ((amzp_glitchOn>0.5)) {
                float gTime  = floor(t * amzp_glitchSpeed);
                float bSize  = amzp_glitchSize * sc;
                float2  block  = floor(uv / max(bSize, 0.01));
                float gRnd   = hashV(block + float2(gTime, amzp_randomSeed * 100.0));
                float thresh = 1.0 - amzp_glitchAmt * amzp_moreOften;
                float fired  = step(thresh, gRnd);

                float cRnd   = hashV(float2(gTime + 5.0, amzp_randomSeed));
                fired *= step(1.0 - amzp_glitchChance * 2.0, cRnd);
                float dispX  = (hashV(block + float2(gTime + 1.0, 0.5)) * 2.0 - 1.0) * bSize * 3.0;
                float3  gCol   = amzTexture(0,
                               clamp(sampleUV + float2(dispX * fired, 0.0), 0.0, 1.0)).rgb;
                col = mix(col, gCol, fired);
            }




            if ((amzp_colorSepOn>0.5)) {
                float cRnd  = hashV(float2(floor(t * 4.0), amzp_randomSeed + 7.0));
                float fired = step(1.0 - amzp_colorSepChance * 2.0, cRnd);
                float ca    = amzp_colorSepAmt * amzp_moreDamage * fired;
                col.r = mix(col.r,
                    amzTexture(0, clamp(sampleUV + float2( ca, 0), 0.0, 1.0)).r,
                    fired);
                col.b = mix(col.b,
                    amzTexture(0, clamp(sampleUV - float2( ca, 0), 0.0, 1.0)).b,
                    fired);
            }




            float luma = dot(col, float3(0.2126, 0.7152, 0.0722));
            luma = clamp(luma + amzp_srcBrightness, 0.0, 1.0);
            luma = clamp((luma - 0.5) * (1.0 + amzp_srcContrast) + 0.5, 0.0, 1.0);

            if ((amzp_colorizeOn>0.5)) {
                float3 shadow    = float3(amzp_shadowR,    amzp_shadowG,    amzp_shadowB);
                float3 midtone   = float3(amzp_midtoneR,   amzp_midtoneG,   amzp_midtoneB);
                float3 highlight = float3(amzp_highlightR, amzp_highlightG, amzp_highlightB);
                float3 colorized = mix(shadow, midtone,   smoothstep(0.0, 0.5, luma));
                colorized      = mix(colorized, highlight, smoothstep(0.5, 1.0, luma));
                col = mix(col, colorized, amzp_colorizeAmt);
            }




            if ((amzp_glowOn>0.5)) {
                float gr    = amzp_glowRadius * 15.0 * sc;
                float2  px    = float2(gr / screen.zw.x, gr / screen.zw.y);
                float lumaC = dot(col, float3(0.2126, 0.7152, 0.0722));
                float gmask = smoothstep(amzp_glowThresh - 0.1, amzp_glowThresh + 0.1, lumaC);

                float3 g0 = amzTexture(0, clamp(sampleUV+float2( px.x, 0.0), 0.0, 1.0)).rgb;
                float3 g1 = amzTexture(0, clamp(sampleUV-float2( px.x, 0.0), 0.0, 1.0)).rgb;
                float3 g2 = amzTexture(0, clamp(sampleUV+float2(0.0,  px.y), 0.0, 1.0)).rgb;
                float3 g3 = amzTexture(0, clamp(sampleUV-float2(0.0,  px.y), 0.0, 1.0)).rgb;
                float3 gBlur = (g0 + g1 + g2 + g3) * 0.25 * gmask;
                float3 glow  = gBlur * amzp_glowIntensity * amzp_moreDamage;
                col = 1.0 - (1.0 - col) * (1.0 - glow * 0.7);
            }




            if ((amzp_scanLinesOn>0.5)) {
                float sd  = float(int(amzp_scanDir));
                float sDist = max(amzp_scanDistance * sc, 1.0);
                float sThk  = amzp_scanThickness / sDist * 0.5;
                sThk = clamp(sThk, 0.01, 0.49);

                float hMask = 1.0;
                float vMask = 1.0;

                if (sd < 0.5 || sd > 1.5) {
                    float hp = fract(uv.y * screen.zw.y / sDist);
                    hMask = mix(0.25, 1.0,
                        1.0 - smoothstep(sThk*0.5, sThk, hp) * (1.0 - smoothstep(1.0-sThk, 1.0-sThk*0.5, hp)));
                }
                if (sd > 0.5) {
                    float vp = fract(uv.x * screen.zw.x / sDist);
                    vMask = mix(0.25, 1.0,
                        1.0 - smoothstep(sThk*0.5, sThk, vp) * (1.0 - smoothstep(1.0-sThk, 1.0-sThk*0.5, vp)));
                }

                col *= hMask * vMask;
            }




            if ((amzp_linesOn>0.5)) {

                float luPos  = fract(uv.y + t * amzp_lineSpeed);
                float luMask = smoothstep(0.0, amzp_lineHeight, luPos) *
                               (1.0 - smoothstep(amzp_lineHeight, amzp_lineHeight*1.1, luPos));

                float ldPos  = fract(uv.y - t * amzp_lineSpeed * 0.7);
                float ldMask = smoothstep(0.0, amzp_lineHeight, ldPos) *
                               (1.0 - smoothstep(amzp_lineHeight, amzp_lineHeight*1.1, ldPos));

                float lineMask = max(luMask, ldMask);
                col = mix(col, col * 1.5, lineMask * 0.6);
            }




            if ((amzp_staticOn>0.5)) {
                float sNoise = hashV(float2(
                    floor(uv.x * screen.zw.x) + floor(t * 30.0) * 1000.0,
                    floor(uv.y * screen.zw.y) + amzp_randomSeed * 500.0
                ));
                col += (sNoise - 0.5) * amzp_staticOpacity * amzp_moreDamage;
            }




            if ((amzp_flickerOn>0.5)) {
                float fRnd  = hashV(float2(floor(t * 15.0), amzp_randomSeed * 30.0));
                float fired = step(1.0 - amzp_flickerChance * 2.0, fRnd);
                float flOp  = mix(1.0, amzp_flickerMin, fired);
                col *= flOp;
            }

            col = clamp(col, 0.0, 1.0);
            amzOutput = float4(mix(src.rgb, col, amzp_blend), src.a);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

