                    float vp = fract(uv.x * screen.zw.x / sDist);
                    vMask = mix(0.25, 1.0,
                        1.0 - smoothstep(sThk*0.5, sThk, vp) * (1.0 - smoothstep(1.0-sThk, 1.0-sThk*0.5, vp)));
                }

                col *= hMask * vMask;
            }




            if ((amzp_linesOn>0.5)) {

                float luPos  = fract(uv.y + t * amzp_lineSpeed);
                float luMask = smoothstep(0.0, amzp_lineHeight, luPos) *
                               (1.0 - smoothstep(amzp_lineHeight, amzp_lineHeight*1.1, luPos));

                float ldPos  = fract(uv.y - t * amzp_lineSpeed * 0.7);
                float ldMask = smoothstep(0.0, amzp_lineHeight, ldPos) *
                               (1.0 - smoothstep(amzp_lineHeight, amzp_lineHeight*1.1, ldPos));

                float lineMask = max(luMask, ldMask);
                col = mix(col, col * 1.5, lineMask * 0.6);
            }




            if ((amzp_staticOn>0.5)) {
                float sNoise = hashV(float2(
                    floor(uv.x * screen.zw.x) + floor(t * 30.0) * 1000.0,
                    floor(uv.y * screen.zw.y) + amzp_randomSeed * 500.0
                ));
                col += (sNoise - 0.5) * amzp_staticOpacity * amzp_moreDamage;
            }




            if ((amzp_flickerOn>0.5)) {
                float fRnd  = hashV(float2(floor(t * 15.0), amzp_randomSeed * 30.0));
                float fired = step(1.0 - amzp_flickerChance * 2.0, fRnd);
                float flOp  = mix(1.0, amzp_flickerMin, fired);
                col *= flOp;
            }

            col = clamp(col, 0.0, 1.0);
            amzOutput = float4(mix(src.rgb, col, amzp_blend), src.a);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
